    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0, "balance check");
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint selfBalBefore = address(this).balance;
        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        if (!reverted) {
            assert(address(this).balance == selfBalBefore + v);
        } else {
            assert(address(this).balance == selfBalBefore);
        }
        assert(c.depositsCount() == depositsBefore);
    }

    receive() external payable {}
}

