pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        uint selfBalBefore = address(this).balance;
        bool reverted;
        try c.withdraw(v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted) {
            assert(address(this).balance == selfBalBefore + v);
        } else {
            assert(address(this).balance == selfBalBefore);
        }
        assertTrue(c.depositsCount() == depositsBefore);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
